import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"ManipBench: Benchmarking Vision-Language Models for Low-Level Robot Manipulation","description":"","frontmatter":{"title":"ManipBench: Benchmarking Vision-Language Models for Low-Level Robot Manipulation","arxiv":"2505.09698","date":"2025-05-14","authors":"Enyu Zhao, Vedant Raval, Hejia Zhang, Jiageng Mao, Zeyu Shangguan, Stefanos Nikolaidis, Yue Wang, Daniel Seita","categories":"cs.RO, cs.AI","topics":"具身智能评测, 视觉语言模型, 低层操作推理","outline":[2,2]},"headers":[],"relativePath":"papers/2505.09698.md","filePath":"papers/2505.09698.md","lastUpdated":null}'),e={name:"papers/2505.09698.md"};function l(i,s,r,m,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="manipbench-benchmarking-vision-language-models-for-low-level-robot-manipulation" tabindex="-1">ManipBench: Benchmarking Vision-Language Models for Low-Level Robot Manipulation <a class="header-anchor" href="#manipbench-benchmarking-vision-language-models-for-low-level-robot-manipulation" aria-label="Permalink to &quot;ManipBench: Benchmarking Vision-Language Models for Low-Level Robot Manipulation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2505.09698" target="_blank" rel="noreferrer">2505.09698</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-05-14</td></tr><tr><td><strong>作者</strong></td><td>Enyu Zhao, Vedant Raval, Hejia Zhang, Jiageng Mao, Zeyu Shangguan, Stefanos Nikolaidis, Yue Wang, Daniel Seita</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>把「机器人该抓哪个点、往哪个格子推」离散成带标注图的多选题，用 12617 道 MCQ 无需 rollout 地评测 33 个 VLM 的低层操作推理，并验证该分数与真机成功率强相关。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>本文基于 arXiv <strong>v2</strong>（CoRL 2025 camera-ready，50 页 30 图，相比 v1 补充了若干新实验）撰写。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>VLM 当高层 planner 已经是成熟做法，但「低层推理」——在一张图上决定夹爪该落在哪个像素、抓起来之后往哪个方向送——是否也能直接交给通用 VLM，社区没有共同的判据。这个空缺代价很高：如果通用 VLM 已经够用，就可以绕开昂贵的、任务专属的机器人数据采集，直接把预训练模型当作 agent 部署；如果不够用，则需要知道差在哪一类操作上。现状是，要回答「哪个 VLM 更适合当机器人的低层大脑」，只能对每个候选模型跑一遍真机 rollout，成本高到无法覆盖几十个模型变体。ManipBench 要做的就是把这个比较变成一次可复现、可扩展、几小时跑完的离线评测。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>已有评测各自解决了一部分问题。NEWTON 与 Octopi 用多选题问物体属性（脆不脆、软不软），PhysBench 用多选题问空间推理——它们评的是「关于物理的知识」，不是「该把夹爪放在哪」。VLABench 评操作任务但假设存在技能库，评的是技能选择而非技能内部的落点。MultiNet 用 Open-X 数据、以轨迹的均方误差打分，作者指出 MSE 在动作多模态时会失真：两条同样合理但方向相反的推法，平均之后是一条谁都不对的轨迹。Open6DOR、ETPBench、GemBench 各自覆盖不同轴，但都没有把「可变形物体」和「动态操作」纳入。论文的表 1 用六个轴（低层推理、任务分解、性能可迁移性评估、真实数据、织物、动态、模型多样性）做了系统比较，ManipBench 是唯一六轴全覆盖的一个。真正的缺口不是「没人做过评测」，而是「没人把低层动作离散成可判分的形式」——因为在连续动作空间里，除了跑 rollout 或算 MSE，没有第三条路。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>出发点是 MOKA 这类工作已经提供的一个现成事实：把观测图用 Grounded SAM 分割、在物体轮廓上采一批候选点、再叠一层网格，VLM 就能通过「选点 + 选格子」来指定一个可执行的低层动作。这条流水线原本是为了让 VLM 能操作机器人，但它顺带完成了一件评测上很关键的事——<strong>把连续动作空间离散成了有限候选集</strong>。一旦动作是从候选集里选的，那么给定一条带真值的演示轨迹，就能把真值落点当正确选项、其余采样点当干扰项，构造出一道随机基线恰好为 25% 的四选一题目。这样评测不需要仿真器、不需要机器人、不需要处理多模态导致的 MSE 失真。剩下的问题只有一个：这样构造出来的 MCQ 分数，究竟和真机上的表现有没有关系？如果没有，这个基准就只是一个漂亮的离线数字。因此论文必须自带一组真机实验来做「性能可迁移性」的验证——这也解释了为什么表 1 要专门列出这一轴。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>低层操作的难点在连续、多模态的动作空间，而这正是评测最难着手的地方。MOKA 式的关键点提示已经把动作压成了「在标注图上选一个候选」，于是评测可以直接借用这个离散化：把真值轨迹的落点当作正确答案，把同一物体上采样出的其他点当作干扰项。评测因此退化成多选题，既保留了「必须理解物体几何与交互后果」这一核心难度，又不必执行任何一步动作。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以 DROID pick-and-place 的一条演示为例：</p><ul><li><strong>预处理</strong>：取该 episode 的起始帧 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与结束帧 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>。用 GPT-4o 从图和任务描述里定位关键物体 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，Grounded SAM 分割出所有物体掩膜，每个掩膜取一个中心点、其余用最远点采样从轮廓取点，最后叠一层 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span> 网格。真值抓取点 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">p</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 若与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 上最近的采样点足够近，就替换为该采样点，保证正确答案确实落在关键物体上。</li><li><strong>出题</strong>：Type 1（Q1）给四条候选轨迹，每条由一个抓取关键点、一个起始图块（含 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">p</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>）和一个结束图块（含 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0197em;">pl</span><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight">ce</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>）组成，四选一。Type 2（Q2）把它拆成两步——先从四个候选里选抓取点，再在给定真值抓取点的条件下选结束图块。所有题目附 CoT 提示。</li><li><strong>三个题源</strong>：公开数据集（DROID 拆成 articulated 与 pick-and-place 两个子集，加 Bridge）共 9180 题（6120 道 Q1 + 3060 道 Q2）；自建织物工作台（3cm 厚 98×78cm 泡沫板 + 87.2cm 高的 RealSense D415i 俯视相机）按十个维度手工出 2662 题；仿真部分覆盖 pick-and-place、articulated、deformable、tool、dynamic 五类，分别取自 SimplerEnv、RLBench、SoftGym 和自建 IsaacSim 打球环境。总计 12617 题。</li><li><strong>评测</strong>：10 个 VLM 家族共 33 个模型，指标是准确率。人类上界由 36 名志愿者通过网页端作答，每种题型答 50–70 题。</li><li><strong>真机验证</strong>：UR5 + Robotiq 2F-85 + 俯视 RGBD，设计 7 个任务（两类 p&amp;p、Fit Apple、Pick Crumpled Cloth、三档 Move Fabric），其目标、语言指令、相机角度、物体的组合从未在基准中共同出现；候选点生成流水线与出题时相同。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>主要的形式化是评分与相关性统计。Q1 的随机基线是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/4</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.25</span></span></span></span>。Q2 由两步合取构成（先选对抓取点，再选对结束图块），若两步独立且各为四选一，随机准确率应为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">0.2</span><span class="mord"><span class="mord">5</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.0625</span></span></span></span>；表 2 实测的 Random 行是 0.061、0.063、0.084，与该推断一致——也就是说 Q2 的低分数并不意味着模型退化，而是难度定义变了，跨题型直接比较绝对分是没有意义的。</p><p>模型稳健性用变异系数衡量：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathrm" style="margin-right:0.0139em;">CV</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.988em;vertical-align:-0.8804em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.1076em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal">μ</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.8804em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">μ</span></span></span></span> 是同一模型在五类操作任务上准确率的标准差与均值，越低越稳。Gemini-2.5-pro 的 CV 为 0.089（闭源最稳），Qwen2.5-VL-32B 为 0.085（开源最稳），它的平均准确率略低于 72B 版本但方差更小。</p><p>可迁移性用三种秩/线性相关同时报告：Pearson <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span>、Spearman <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span>、Kendall <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span>，样本是 8 个模型的（MCQ 平均准确率，真机总成功率）配对。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：VLM 到底会不会做低层推理？</strong> 答案是「会一点，但离人差得远」。Gemini-2.5-pro 在三个 Q1 子集上分别是 0.916 / 0.909 / 0.869，o1 在 DROID p&amp;p 的 Q2 上最好（0.542）；人类在 Q1 上是 0.880–0.990、在 Q2 上是 0.635–0.940。所有小于 2B 的开源模型基本等于甚至差于随机，InternVL2-1B 在 Bridge Q1 上是 0.015——低于随机这么多，说明它多半连输出格式都没遵守。按任务类别聚合，pick-and-place 平均 0.525，articulated 0.396，dynamic 0.357，后两类明显更难。织物维度上模型间标准差很大，而人类在各维度上都稳定，说明难度不是题目本身造成的。</p><p><strong>问题二：这个离线分数能预测真机表现吗？</strong> 8 个模型 × 7 任务 × 3 次的真机实验给出 Pearson 0.889（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.003</span></span></span></span>）、Spearman 0.850（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.007</span></span></span></span>）、Kendall 0.691（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.018</span></span></span></span>）。拆开看，织物维度的相关最强（Pearson 0.950），仿真题源最弱（0.779），其中 Sweep Object 只有 0.270（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.518</span></span></span></span>），DROID articulated 的 Q2 只有 0.426（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.293</span></span></span></span>）——也就是说「整体强相关」并非每个子集都成立，有若干子集在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8</span></span></span></span> 下完全不显著。</p><p>需要如实指出几处论文自身的问题：正文在「Results on MCQs from public robotic manipulation datasets」一段把表 2 引成了 Table 3（交叉引用笔误）；表 4 中 InternVL2.5-26B 一行逐格加起来是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">3</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">11</span></span></span></span>，但 Total 列写的是 8/21，其余七行都自洽，这一行必有一误。此外 Move Fabric Hard 上八个模型全部 0/3，该任务在本轮实验里没有任何区分度。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：ManipBench 把低层操作推理离散成 MOKA 式的关键点多选题，构造了 12617 道题、覆盖 pick-and-place / articulated / deformable / tool / dynamic 五类。它评测了 10 个家族 33 个 VLM，发现最强的 Gemini-2.5-pro 在 Q1 上接近 0.9 但在 Q2 上不到 0.46，而人类分别是 0.88–0.99 和 0.635–0.94。开源模型呈现清晰的规模律（各家族准确率与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9386em;vertical-align:-0.2441em;"></span><span class="mop"><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.207em;"><span style="top:-2.4559em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">10</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2441em;"><span></span></span></span></span></span></span></span></span></span> 参数量的 Pearson <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span> 在 0.890–0.998），但 2B 以下等于随机。7 个真机任务上，MCQ 平均分与成功率的 Pearson 是 0.889。分项相关性并不一致：织物题最强（0.950），工具类 Sweep Object 几乎无关（0.270）。</p><p><strong>3 句话版</strong>：把机器人低层动作压成「在标注图上选点」的多选题，就能不跑 rollout 地大规模评测 VLM。最强模型显著优于随机但明显低于人类，articulated 与 dynamic 是最弱的两类。基准分数与真机成功率在 8 个模型上强相关，但这一相关性依赖于真机也采用同样的「从候选中选」接口。</p><p><strong>1 句话版</strong>：低层操作推理可以被离散成多选题来评测，而这个离线分数确实能预测同接口下的真机表现。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最关键的假设是：<strong>「从预设候选里做选择」这一接口，能代表 VLM 在真实部署中被使用的方式</strong>。作者在 Limitations 里自己点了这一条——基准和真机实验都让 VLM 从固定选项中挑，而实际部署时 VLM 未必有候选集可选。这个假设一旦不成立，0.889 的相关性就失去外推价值：它证明的可能只是「同一个 MOKA 流水线下，选得准的模型在同一流水线的真机版本里也选得准」，而不是「更强的低层物理理解带来更好的操作」。这一点尤其值得警惕，因为真机的候选点生成与出题用的是同一条流水线（GPT-4o 找关键物体 → Grounded SAM → 轮廓 FPS 采点），两端共享同一组失败模式（分割错、关键物体找错），共享的噪声本身就会制造相关性。论文为该假设提供的证据是七个「组合从未在基准中出现」的新任务，但没有提供任何一个换接口（例如让模型直接回归坐标）的对照。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做的判决实验：从 Bridge Q1 里随机取 500 题，跑三个配置——(a) 原样；(b) 随机置换选项标签顺序（A/B/C/D 重排）；(c) 盲测，把图像替换成纯色但保留全部文字选项描述。取三个规模档的模型（如 Qwen2.5-VL 的 3B / 7B / 72B）。判据：如果 (b) 使准确率明显掉，说明存在选项位置偏置，绝对分被高估；如果 (c) 的准确率已经明显高于 0.25，说明相当一部分信号来自语言先验（例如「抓把手」这种常识），而非对图像中几何关系的理解。反之，若 (b)(c) 都接近随机而 (a) 保持高分，则支持论文的解读。这个实验不需要机器人、不需要重新出题，只改提示与输入。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>反对者的最强攻击是：<strong>0.889 的相关性由两端的极端模型撑起，而非真的反映连续的能力梯度</strong>。真机总成绩里 Gemini-2.5-pro 是 18/21、GLM-4V-9B 是 2/21，两端相隔 16 次成功；中间五个模型分布在 5/21 到 15/21 之间，而每格只跑 3 次——1 次成功等于 4.8 个百分点，中间模型之间的差异完全落在单次试验的噪声里。更麻烦的是 Move Fabric Hard 上全体 0/3，这一列对相关性没有任何贡献却占了 1/7 的权重。攻击方案：只在中间五个模型上重算 Pearson，并把每格试验次数从 3 提到 20；若相关性掉到不显著，则「基准可预测真机」的结论只在「区分极强与极弱模型」的粗粒度上成立。另一个替代解释同样致命：MCQ 与真机成绩可能同时被「能否遵守输出格式」主导——InternVL2-1B 在 Bridge Q1 上 0.015（远低于随机）正是格式失败的指纹，而这类模型在真机上也必然拿 0，两端因同一个非物理原因对齐。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动的局限</strong>：四选一强制模型给出单点估计，而低层操作本质是多模态的——一块布可以从左上角抓也可以从右下角抓，两者都对。MultiNet 用 MSE 时踩的正是这个坑，ManipBench 用「唯一正确选项」绕开了它，但也因此测不出模型对「多解」的认识。</p><p><strong>新的 framing</strong>：把基准从「判别题」改成「分布校准题」。不再问「哪个点是对的」，而是让 VLM 在 16 个候选点上输出一个概率分布，用同一 episode（或同一场景的多条人类演示）的真值落点经验分布作为参照，以严格适当评分规则（strictly proper scoring rule）打分。</p><p><strong>可借鉴的相邻领域</strong>：气象与流行病预报里成熟的概率评分体系——log score、CRPS、可靠性图与 ECE，以及它们与「锐度 / 校准」二分的解释框架。这套工具正是为「真值本身是分布」的场景设计的。</p><p><strong>第一个实验</strong>：在 Bridge 与织物子集上，为每张图采 16 个候选点，让模型输出 softmax 分布；同时对同一初始状态收集 5 条不同的人类演示作为经验真值分布。报告 log-loss、CRPS 与 ECE，并与现有的四选一准确率做排名对比。如果排名发生显著重排，说明现有基准奖励的是「敢押单点」而非「懂物理」，这将直接改变「哪个 VLM 适合当机器人低层大脑」的答案。</p>',40)])])}const d=a(e,[["render",l]]);export{g as __pageData,d as default};
